    const payload: ?[]const u8 = null;

    var operation_headers = std.ArrayList(std.http.Header).empty;
    defer operation_headers.deinit(allocator);
    var operation_header_values = std.ArrayList([]u8).empty;
    defer {
        for (operation_header_values.items) |item| allocator.free(item);
        operation_header_values.deinit(allocator);
    }
    var auth_header: ?[]u8 = null;
    defer if (auth_header) |value| allocator.free(value);
    if (client.api_key.len > 0) {
        auth_header = try std.fmt.allocPrint(allocator, "Bearer {s}", .{client.api_key});
        try operation_headers.append(allocator, .{ .name = "Authorization", .value = auth_header.? });
    }

    return requestRawWithExtraHeaders(client, std.http.Method.HEAD, uri_buf.written(), payload, operation_headers.items);
}

/////////////////
// Summary:
// Fetch a file from a module's bundled static assets.
//
// Description:
// `path` is resolved relative to the module's bundle root; an unknown module or missing file returns 404.
//
// Both path parameters can themselves contain `/`. A module is served under the name its `package.json`
// declares, which carries an owner scope (`@scope/name`) for anything published to a registry, and `path`
// addresses sub-directories of the bundle. A client that percent-encodes each parameter as one path segment
// turns those slashes into `%2F` and asks for something no server serves, so build the request path rather
// than passing the values through a per-segment encoder.
//
pub fn get_module_file(client: *Client, name: []const u8, path: []const u8) !void {
    var raw = try get_module_fileRaw(client, name, path);
    defer raw.deinit();
    if (raw.status.class() != .success) return error.ResponseError;
}

pub fn get_module_fileRaw(client: *Client, name: []const u8, path: []const u8) !RawResponse {
    const allocator = client.allocator;
    var uri_buf: std.Io.Writer.Allocating = .init(allocator);
    defer uri_buf.deinit();
    try uri_buf.writer.print("{s}/modules/{s}/{s}", .{ client.base_url, name, path });
    const payload: ?[]const u8 = null;

    var operation_headers = std.ArrayList(std.http.Header).empty;
    defer operation_headers.deinit(allocator);
    var operation_header_values = std.ArrayList([]u8).empty;
    defer {
        for (operation_header_values.items) |item| allocator.free(item);
        operation_header_values.deinit(allocator);
    }
    var auth_header: ?[]u8 = null;
    defer if (auth_header) |value| allocator.free(value);
    if (client.api_key.len > 0) {
        auth_header = try std.fmt.allocPrint(allocator, "Bearer {s}", .{client.api_key});
        try operation_headers.append(allocator, .{ .name = "Authorization", .value = auth_header.? });
    }

    return requestRawWithExtraHeaders(client, std.http.Method.GET, uri_buf.written(), payload, operation_headers.items);
}

/// Host-provided HTTP transport. The JS shim implements this against
/// browser `fetch()` (via SharedArrayBuffer + Atomics so this looks
/// synchronous to Zig). Returns the number of bytes written to
/// `response_buf`, or a negative value on transport failure /
/// non-2xx status.
extern fn js_rest_request(
    method_ptr: [*]const u8,
    method_len: usize,
    url_ptr: [*]const u8,
    url_len: usize,
    body_ptr: [*]const u8,
    body_len: usize,
    response_buf: [*]u8,
    response_max: usize,
) i32;
